scwin.btn_trigger2_onclick = function (e) {
	//spplyAmt column을 2번째로 이동
	gr_gridView2.setColumnOrder([0, 9, 1, 2, 3, 4, 5, 6, 7, 8, 10, 11]);
};

scwin.btn_trigger3_onclick = function (e) {
	/*단일 그리드 다운로드 */
	// gr_gridView2.advancedExcelDownload({
	//     type : "1",  useStyle : "true", columnMove : "true", removeColumns : "3,5,7"
	// });

	/* 그리드 멀티다운로드 */
	var options = {
			common: {
				"fileName" : "dataList.xlsx",
				"multipleSheet": "true",
				"showProcess" : true,
				"onSuccessCallback" : scwin.gridExcelSuccessCallback,
				"onFailureCallback" : ""
			},
			excelInfo: [
				{
					"gridId" : gr_gridView2.getID(),
					"sheetName" : "첫번째 sheet",
					"useStyle" : "true",
					"columnMove" : "true",
					"removeColumns" : "3,5,7"
				},
				{
					"gridId" : gr_gridView2.getID(),
					"sheetName" : "두번째 sheet",
					"useStyle" : "true",
					"columnMove" : "true",
					"removeColumns" : ""
				}
			]
		};

		WebSquare.util.multipleExcelDownload( options );
};
